/** The title chunk of an overlay locale (English titles are in the manifest). */
export function loadLessonTitles(locale: OverlayLocale): Promise<LessonTitleChunk> {
  switch (locale) {
    case "es":
      return import('./lesson-chunks/lessons-titles-es');
    case "ko":
      return import('./lesson-chunks/lessons-titles-ko');
  }
}
